function ensureNarrowcasting(tenant){tenant.narrowcasting||={};tenant.narrowcasting.screens||=[];for(let number=1;number<=5;number++){if(!tenant.narrowcasting.screens.some(item=>item.number===number))tenant.narrowcasting.screens.push({id:`screen-${number}`,number,name:`Scherm ${number}`,imageDuration:10,media:[]});}tenant.narrowcasting.screens=tenant.narrowcasting.screens.filter(item=>item.number>=1&&item.number<=5).sort((a,b)=>a.number-b.number);for(const screen of tenant.narrowcasting.screens)screen.media||=[];return tenant.narrowcasting;}
