function ensureWebsite(tenant){tenant.website||={};tenant.website.activities||=[];tenant.website.news||=[];tenant.website.faqs||=[];tenant.website.tourSlots||=[];tenant.website.tourSchedules||=[];tenant.website.tourRequests||=[];tenant.website.volunteers||=[];tenant.website.volunteerAvailability||=[];tenant.website.emailOutbox||=[];return tenant.website;}
